// END GENERATED MEASUREMENT ARRAYS
// Geometry update only (once per 64 PCM frames), never per audio sample.
inline void interpolate(float azimuth,float elevation,bool use44100,
                        EarBank& destination) noexcept {
    if(!std::isfinite(azimuth)||!std::isfinite(elevation)) {
        for(auto& ear:destination)ear.fill(0.f);
        return;
    }
    float normalized=std::fmod(azimuth,360.f);
    if(normalized<0.f)normalized+=360.f;
    const bool swapped=normalized>180.f;
    const float absolute=swapped?360.f-normalized:normalized;
    const float el=std::clamp(elevation,static_cast<float>(elevationMin),
                             static_cast<float>(elevationMax));
    const Row* rows=use44100?rows44100:rows48000;
    int high=0;
    while(high<elevationCount-1 && el>rows[high].elevation)++high;
    const int low=std::max(0,high-1);
    const float blend=low==high?0.f:(el-rows[low].elevation)/
                                     (rows[high].elevation-rows[low].elevation);
    struct Pair {const std::int16_t (*a)[hrir::taps];
                 const std::int16_t (*b)[hrir::taps];float t;};
    // Span calculated once per elevation, not inside FIR tap loops.
    const auto span=[&](const Row& row) noexcept {
        int h=0;
        while(h<row.count-1 && absolute>row.angles[h])++h;
        const int l=std::max(0,h-1);
        const float t=l==h?0.f:std::clamp((absolute-row.angles[l])/
            static_cast<float>(row.angles[h]-row.angles[l]),0.f,1.f);
        return Pair{row.pcm[l],row.pcm[h],t};
    };
    const Pair lower=span(rows[low]),upper=span(rows[high]);
    constexpr float scale=1.f/32768.f;
    for(int ear=0;ear<2;++ear){
        const int measuredEar=swapped?1-ear:ear;
        for(int k=0;k<hrir::taps;++k) {
            const float a=lower.a[measuredEar][k]*(1.f-lower.t)+
                          lower.b[measuredEar][k]*lower.t;
            const float b=upper.a[measuredEar][k]*(1.f-upper.t)+
                          upper.b[measuredEar][k]*upper.t;
            destination[ear][k]=scale*(a*(1.f-blend)+b*blend);
        }
    }
}
static_assert(rows44100[4].elevation==0 && rows48000[4].elevation==0);
static_assert(rows44100[4].pcm==hrir::normal44100);
static_assert(rows48000[4].pcm==hrir::normal48000);
